":"leg","shape":{"type":"box","size":[0.3,0.14,0.42],"bevel":0.06},"position":[0,-0.2,0.05],"rotation":[0,0,0],"scale":[1,1,1],"materialId":"shell-dark","mirrorX":false}],"pose":{"description":"Standing, left arm raised in a wave, head tilted","adjustments":[]},"camera":{"position":[2.6,2.1,4.6],"target":[0,1,0],"fov":32},"lighting":{"preset":"soft","keyColor":"#ffffff","intensity":1.05},"background":"#e5eef0","customParts":[{"id":"gear","name":"Wind-up gear","description":"A toothed gear with a hole: needs a 2D path with holes, which the extrude primitive can't express.","code":"const teeth = 10, inner = 0.15, outer = 0.2;
const s = new THREE.Shape();
for (let i = 0; i < teeth * 2; i++) {
  const a = (i / (teeth * 2)) * Math.PI * 2;
  const r = i % 2 === 0 ? outer : inner;
  const x = Math.cos(a) * r, y = Math.sin(a) * r;
  if (i === 0) s.moveTo(x, y); else s.lineTo(x, y);
}
s.closePath();
const hole = new THREE.Path();
hole.absarc(0, 0, 0.05, 0, Math.PI * 2, true);
s.holes.push(hole);
const g = new THREE.ExtrudeGeometry(s, { depth: 0.05, bevelEnabled: false, curveSegments: 12 });
g.translate(0, 0, -0.025);
return g;","parentId":"body","position":[0,0.05,-0.4],"rotation":[0,0,0],"scale":[1.4,1.4,1],"materialId":"metal"}],"notes":"Back of the robot inferred; the gear is a guess from the wind-up key silhouette."}}
